import json
from pathlib import Path

from .core import Challenge
from .simulation import PuzzleAlgorithm, Simulation


def run_algorithm(algorithm: PuzzleAlgorithm, challenge: Challenge, output: str | Path) -> dict:
    """Always export the successful prefix, even if participant code raises."""
    simulation = Simulation(challenge)
    error = None
    try:
        algorithm.solve(simulation)
    except Exception as exception:
        error = f"{type(exception).__name__}: {exception}"
    Path(output).write_text(json.dumps(simulation.to_trace(), indent=2) + "\n", encoding="utf-8")
    return {
        "solved": simulation.is_solved,
        "error": error,
        "actions": len(simulation.to_trace()["actions"]),
        "output": str(output),
    }
